<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\OAuth\Profile\Domain\OidcProfile;
use Civi\Lughauth\Features\OAuth\Profile\Domain\OidcProfileData;
use Civi\Lughauth\Features\OAuth\Profile\Domain\Gateway\ProfileGateway;

/**
 * REST API controller for the authenticated user's own OIDC profile resource.
 *
 * Exposes GET /api/me/profile and PUT /api/me/profile endpoints that allow a bearer-token
 * authenticated user to retrieve and update their own OIDC profile claims without any
 * admin-level access.  The controller reads the caller's identity from the shared Context
 * and rejects anonymous requests with HTTP 401.
 *
 * The GET handler returns the current profile serialised as ProfileApiDTO, or an empty
 * DTO when no profile record has been created yet.  The PUT handler performs an upsert
 * through ProfileGateway::save() inside an explicit SQL transaction managed by SqlTemplate,
 * and returns the persisted profile on success.
 *
 * Distributed tracing spans are opened for every public method via TracerAwareTrait,
 * and exceptions are recorded on the active span before being re-thrown so that
 * trace-based alerting can correlate errors to specific API calls.
 */
class ProfileMeController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly Context $context,
        private readonly SqlTemplate $sql,
        private readonly ProfileGateway $gateway,
    ) {
    }

    /**
     * Handles GET /api/me/profile — returns the caller's OIDC profile as JSON.
     *
     * Throws UnauthorizedException for anonymous callers.  Returns an empty ProfileApiDTO
     * when the user has not yet created a profile record.
     */
    #[OA\Get(
        path: '/api/me/profile',
        summary: 'Get own user profile',
        tags: ['Profile'],
        security: [['bearerAuth' => []]],
        responses: [
            new OA\Response(response: 200, description: 'Ok', content: new OA\JsonContent(type: 'object', ref: '#/components/schemas/ProfileApiDTO')),
            new OA\Response(response: 401, description: 'Unauthorized'),
        ]
    )]
    public function get(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Get own profile");
        $span = $this->startSpan("Get own profile");
        try {
            $identity = $this->context->getIdentity();
            if ($identity->anonymous || null === $identity->id) {
                throw new UnauthorizedException('Authentication required');
            }
            $profile = $this->gateway->findByUser($identity->id);
            $dto = $profile !== null ? $this->mapToDto($profile) : new ProfileApiDTO();
            $encoded = json_encode($dto);
            $response->getBody()->write($encoded !== false ? $encoded : '{}');
            return $response->withStatus(200)->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Handles PUT /api/me/profile — creates or updates the caller's OIDC profile.
     *
     * Parses the JSON request body into OidcProfileData, delegates to ProfileGateway::save()
     * inside a transaction, and returns the persisted profile as JSON with HTTP 200.
     */
    #[OA\Put(
        path: '/api/me/profile',
        summary: 'Create or update own user profile',
        tags: ['Profile'],
        security: [['bearerAuth' => []]],
        requestBody: new OA\RequestBody(content: new OA\JsonContent(type: 'object', ref: '#/components/schemas/ProfileApiDTO')),
        responses: [
            new OA\Response(response: 200, description: 'Ok', content: new OA\JsonContent(type: 'object', ref: '#/components/schemas/ProfileApiDTO')),
            new OA\Response(response: 401, description: 'Unauthorized'),
            new OA\Response(response: 422, description: 'Constraint error'),
        ]
    )]
    public function put(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Upsert own profile");
        $span = $this->startSpan("Upsert own profile");
        $this->sql->begin();
        try {
            $identity = $this->context->getIdentity();
            if ($identity->anonymous || null === $identity->id) {
                throw new UnauthorizedException('Authentication required');
            }
            $data = $this->readData($request);
            $profile = $this->gateway->save($identity->id, $data);
            $this->sql->commit();
            $dto = $this->mapToDto($profile);
            $encoded = json_encode($dto);
            $response->getBody()->write($encoded !== false ? $encoded : '{}');
            return $response->withStatus(200)->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readData(ServerRequestInterface $request): OidcProfileData
    {
        $parsed = $request->getParsedBody() ?? [];
        $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
        return new OidcProfileData(
            givenName: isset($body['givenName']) ? (string) $body['givenName'] : null,
            familyName: isset($body['familyName']) ? (string) $body['familyName'] : null,
            middleName: isset($body['middleName']) ? (string) $body['middleName'] : null,
            nickname: isset($body['nickname']) ? (string) $body['nickname'] : null,
            preferredUsername: isset($body['preferredUsername']) ? (string) $body['preferredUsername'] : null,
            pictureUrl: isset($body['pictureUrl']) ? (string) $body['pictureUrl'] : null,
            websiteUrl: isset($body['websiteUrl']) ? (string) $body['websiteUrl'] : null,
            gender: isset($body['gender']) ? (string) $body['gender'] : null,
            birthdate: isset($body['birthdate']) ? (string) $body['birthdate'] : null,
            zoneinfo: isset($body['zoneinfo']) ? (string) $body['zoneinfo'] : null,
            locale: isset($body['locale']) ? (string) $body['locale'] : null,
            phoneNumber: isset($body['phoneNumber']) ? (string) $body['phoneNumber'] : null,
            phoneNumberVerified: isset($body['phoneNumberVerified']) ? (bool) $body['phoneNumberVerified'] : null,
            addressJson: isset($body['addressJson']) ? (string) $body['addressJson'] : null,
        );
    }

    private function mapToDto(OidcProfile $profile): ProfileApiDTO
    {
        $dto = new ProfileApiDTO();
        $dto->uid = $profile->uid;
        $dto->user = ['$ref' => $profile->userUid];
        $dto->givenName = $profile->givenName;
        $dto->familyName = $profile->familyName;
        $dto->middleName = $profile->middleName;
        $dto->nickname = $profile->nickname;
        $dto->preferredUsername = $profile->preferredUsername;
        $dto->pictureUrl = $profile->pictureUrl;
        $dto->websiteUrl = $profile->websiteUrl;
        $dto->gender = $profile->gender;
        $dto->birthdate = $profile->birthdate;
        $dto->zoneinfo = $profile->zoneinfo;
        $dto->locale = $profile->locale;
        $dto->phoneNumber = $profile->phoneNumber;
        $dto->phoneNumberVerified = $profile->phoneNumberVerified;
        $dto->addressJson = $profile->addressJson;
        $dto->updatedAt = $profile->updatedAt;
        $dto->version = $profile->version;
        return $dto;
    }

    private function toOidcClaims(OidcProfile $profile): array
    {
        $claims = [];

        $nameParts = array_filter([$profile->givenName, $profile->familyName]);
        if ($nameParts !== []) {
            $claims['name'] = implode(' ', $nameParts);
        }

        $mapping = [
            'given_name'            => $profile->givenName,
            'family_name'           => $profile->familyName,
            'middle_name'           => $profile->middleName,
            'nickname'              => $profile->nickname,
            'preferred_username'    => $profile->preferredUsername,
            'picture'               => $profile->pictureUrl,
            'website'               => $profile->websiteUrl,
            'gender'                => $profile->gender,
            'birthdate'             => $profile->birthdate,
            'zoneinfo'              => $profile->zoneinfo,
            'locale'                => $profile->locale,
            'phone_number'          => $profile->phoneNumber,
        ];

        foreach ($mapping as $key => $value) {
            if ($value !== null) {
                $claims[$key] = $value;
            }
        }

        if ($profile->phoneNumberVerified !== null) {
            $claims['phone_number_verified'] = $profile->phoneNumberVerified;
        }

        if ($profile->addressJson !== null) {
            $decoded = json_decode($profile->addressJson, true);
            if (is_array($decoded)) {
                $claims['address'] = $decoded;
            }
        }

        if ($profile->updatedAt !== null) {
            $ts = strtotime($profile->updatedAt);
            if ($ts !== false) {
                $claims['updated_at'] = $ts;
            }
        }

        return $claims;
    }
}
